import math

ALPHABET_SIZE = 26
GROUP_SIZE = 5


def _check_coprime(a):
    if math.gcd(a, ALPHABET_SIZE) != 1:
        raise ValueError("a and m must be coprime.")


def _modular_inverse(a, m):
    return pow(a, -1, m)


def encode(plain_text, a, b):
    _check_coprime(a)

    encoded = []
    for char in plain_text.lower():
        if char.isalpha():
            index = ord(char) - ord("a")
            new_index = (a * index + b) % ALPHABET_SIZE
            encoded.append(chr(new_index + ord("a")))
        elif char.isdigit():
            encoded.append(char)

    groups = [
        "".join(encoded[i : i + GROUP_SIZE])
        for i in range(0, len(encoded), GROUP_SIZE)
    ]
    return " ".join(groups)


def decode(ciphered_text, a, b):
    _check_coprime(a)

    a_inverse = _modular_inverse(a, ALPHABET_SIZE)
    decoded = []
    for char in ciphered_text:
        if char.isalpha():
            index = ord(char) - ord("a")
            new_index = (a_inverse * (index - b)) % ALPHABET_SIZE
            decoded.append(chr(new_index + ord("a")))
        elif char.isdigit():
            decoded.append(char)

    return "".join(decoded)
